// Tool 3 — farm-margin estimator (live board price + the grower's own numbers)
function agMarginCard(pr) {
  if (!pr.ok) return toolCard('agMargin', 'Farm-margin estimator', 'What this crop pencils out to per acre.', failBox(pr.reason));
  var opts = pr.rows.filter(function (r) { return r.ok; }).map(function (r) {
    return '<option value="' + esc(r.crop) + '">' + esc(r.label) + ' — ' + money(r.price, 2) + '/bu</option>';
  }).join('');
  var body =
    '<div class="agform">' +
    '<div><label for="agCrop">Crop</label><select id="agCrop">' + opts + '</select></div>' +
    '<div><label for="agAcres">Acres</label><input id="agAcres" type="number" min="1" step="1" value="500"></div>' +
    '<div><label for="agYield">Yield (bu/acre)</label><input id="agYield" type="number" min="1" step="1"></div>' +
    '<div><label for="agBasis">Basis ($/bu)</label><input id="agBasis" type="number" step="0.01" value="-0.30"></div>' +
    '<div><label for="agCost">Your cost ($/acre)</label><input id="agCost" type="number" min="0" step="1" placeholder="enter yours"></div>' +
    '</div><div class="agout" id="agOut"></div>' +
    '<div class="agnote" id="agNote"></div>';
  return toolCard('agMargin', 'Farm-margin estimator',
    'Live board price against <b>your</b> yield, basis and cost. Nothing is assumed about your operation: yield starts at the US average and cost starts blank, because your cost is the number that decides this.',
    body);
}

function wireMarginCalc(pr) {
  var byCrop = {};
  pr.rows.forEach(function (r) { if (r.ok) byCrop[r.crop] = r; });
  var elCrop = EL('agCrop'), elAcres = EL('agAcres'), elYield = EL('agYield'),
      elBasis = EL('agBasis'), elCost = EL('agCost'), out = EL('agOut'), note = EL('agNote');
  if (!elCrop) return;

  function calc() {
    var r = byCrop[elCrop.value];
    if (!r) return;
    var acres = parseFloat(elAcres.value) || 0;
    var yld = parseFloat(elYield.value) || 0;
    var basis = parseFloat(elBasis.value); if (!isFinite(basis)) basis = 0;
    var cost = parseFloat(elCost.value);
    var cash = r.price + basis;
    var revAcre = cash * yld;
    var hasCost = isFinite(cost) && cost >= 0;
    var marginAcre = hasCost ? revAcre - cost : null;
    var breakeven = (hasCost && yld > 0) ? cost / yld : null;

    out.innerHTML =
      '<div><div class="n">' + money(cash, 2) + '</div><div class="k">Your cash price per bushel<br>board ' + money(r.price, 2) + ' + basis ' + money(basis, 2) + '</div></div>' +
      '<div><div class="n">' + money(revAcre, 0) + '</div><div class="k">Revenue per acre</div></div>' +
      '<div><div class="n">' + (marginAcre == null ? '—' : money(marginAcre, 0)) + '</div><div class="k">' + (marginAcre == null ? 'Enter your cost per acre' : 'Margin per acre') + '</div></div>' +
      '<div><div class="n">' + (marginAcre == null ? '—' : money(marginAcre * acres, 0)) + '</div><div class="k">Margin on ' + (acres || 0) + ' acres</div></div>';

    var msg = '';
    if (breakeven != null) {
      msg += '<b>Break-even cash price: ' + money(breakeven, 2) + '/bu</b> at ' + yld + ' bu/acre. ' +
        'You are ' + (cash >= breakeven ? 'above' : 'below') + ' it by ' + money(Math.abs(cash - breakeven), 2) + '. ';
    }
    msg += 'Board price is the ' + esc(r.label) + ' front-month future (' + esc(r.symbol) + '), ' +
      (r.changeDay != null ? signed(r.changeDay) + ' on the day, ' : '') +
      (r.changeMonth != null ? signed(r.changeMonth) + ' on the month. ' : '');
    msg += esc(pr.note) + ' Basis defaults to -$0.30; ask your elevator for today\'s real number. ' +
      'For a starting point on costs by crop and region, see the USDA ERS ' +
      '<a href="https://www.ers.usda.gov/data-products/commodity-costs-and-returns" target="_blank" rel="noopener">commodity costs and returns</a> tables. ' +
      'This is an arithmetic calculator, not marketing advice.';
    note.innerHTML = msg;
  }

  function setYieldDefault() {
    var r = byCrop[elCrop.value];
    if (r && r.typicalYield) elYield.value = r.typicalYield;
  }
  elCrop.addEventListener('change', function () { setYieldDefault(); calc(); });
  [elAcres, elYield, elBasis, elCost].forEach(function (e) { e.addEventListener('input', calc); });
  setYieldDefault();
  calc();
}

