// ── TRADE: who America buys from, and what it sells back ───────────────────
function renderTradeTools(host) {
  host.innerHTML = '<div class="muted">Reading the trade ledger…</div>';
  fetch('/api/trade-tools').then(function (r) { return r.json(); }).then(function (j) {
    if (!j.ok) { host.innerHTML = toolCard('trdWho', 'Who America buys from', 'Goods in, goods out, by partner.', failBox(j.reason)); return; }
    var rows = j.partners.map(function (p) {
      var gapCol = p.gap < 0 ? 'var(--red)' : 'var(--green)';
      return '<div class="agrow" style="grid-template-columns:1fr 104px 104px"><div class="nm">' +
        '<a href="' + esc(p.url) + '" target="_blank" rel="noopener">' + esc(p.name) + '</a>' +
        '<em>bought ' + bigUsd(p.imports) + (p.importsChangeYear != null ? ' (' + (p.importsChangeYear > 0 ? '+' : '') + p.importsChangeYear + '% y/y)' : '') +
        ' · sold ' + bigUsd(p.exports) + (p.exportsChangeYear != null ? ' (' + (p.exportsChangeYear > 0 ? '+' : '') + p.exportsChangeYear + '% y/y)' : '') + '</em>' +
        (p.boughtPerDollarSold != null ? '<em>$' + p.boughtPerDollarSold.toFixed(2) + ' bought for every $1 sold</em>' : '') + '</div>' +
        '<div class="agval" style="color:' + gapCol + '">' + bigUsd(Math.abs(p.gap)) + '<em>' + (p.gap < 0 ? 'deficit' : 'surplus') + '</em></div>' +
        '<div class="agval" style="font-size:.68rem">' + esc(p.asOf || '') + '<em>month</em></div></div>';
    }).join('');
    var prices = j.prices.map(function (p) {
      if (p.ok === false) return '<div class="agrow" style="grid-template-columns:1fr 96px"><div class="nm">' + esc(p.label) + '<em>' + esc(p.reason) + '</em></div><div class="agval">n/a</div></div>';
      return '<div class="agrow" style="grid-template-columns:1fr 96px"><div class="nm">' +
        '<a href="' + esc(p.url) + '" target="_blank" rel="noopener">' + esc(p.label) + '</a><em>' + esc(p.what) + '</em></div>' +
        '<div class="agval">' + (p.changeYear == null ? 'n/a' : signed(p.changeYear)) + '<em>in a year</em></div></div>';
    }).join('');
    var body =
      '<div style="margin-top:4px"><div class="mig-h">By partner, newest month</div>' + rows + '</div>' +
      (j.unavailablePartners && j.unavailablePartners.length ? '<div class="agnote">Not available on this read: ' + esc(j.unavailablePartners.join(', ')) + '.</div>' : '') +
      '<div style="margin-top:18px"><div class="mig-h">What imported goods cost now</div>' + prices + '</div>' +
      (j.totalBalance != null ? '<div class="agnote" style="color:var(--ink)"><b>Total goods and services balance: ' + bigUsd(j.totalBalance) + '</b> for ' + esc(j.totalBalanceAsOf || '') + '. This one DOES include services.</div>' : '') +
      '<div class="agnote">' + esc(j.note) + '<br><b>Limits.</b> ' + esc(j.caveat) + ' ' +
      'Source: <a href="' + esc(j.sourceUrl) + '" target="_blank" rel="noopener">' + esc(j.source) + '</a>.</div>';
    host.innerHTML = toolCard('trdWho', 'Who America buys from, and what it sells back',
      'The monthly ledger, partner by partner, plus the number that actually reaches a household: what imported goods cost now against a year ago.', body);
  }).catch(function () { host.innerHTML = failBox('The trade data service did not respond.'); });
}

