/**
 * Turn a Subscribe press into a real Stripe checkout.
 *
 * The button sends only the DOMAIN and the RUNG. The price is looked up on the server from
 * lib/offer-catalog.js, so nothing here can ask to pay less, and there is no amount in this
 * file that could drift from what is actually charged.
 *
 * If payments are not switched on yet the server says so in plain words and we show that,
 * rather than a dead button or a silent failure.
 */
function wireBuyButtons(host) {
  if (!host || host.__buyWired) return;
  host.__buyWired = true;
  host.addEventListener('click', function (ev) {
    var btn = ev.target && ev.target.closest ? ev.target.closest('.pbuy') : null;
    if (!btn) return;
    ev.preventDefault();

    // P10 is priced per engagement, so there is no amount to charge. Send them to the
    // enquiry form rather than showing a Subscribe button that cannot complete.
    if (btn.getAttribute('data-enquire')) {
      var form = EL('eaForm') || EL('capForm');
      if (form) {
        form.scrollIntoView({ behavior: 'smooth', block: 'center' });
        var input = EL('eaEmail') || EL('capEmail');
        if (input) setTimeout(function () { input.focus(); }, 400);
      }
      return;
    }

    var row = btn.closest('.prow');
    var note = row && row.parentNode ? row.parentNode.querySelector('.pbuynote') : null;
    if (note) note.remove();

    var label = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Opening…';

    function say(msg, bad) {
      btn.disabled = false;
      btn.textContent = label;
      var d = document.createElement('div');
      d.className = 'pbuynote' + (bad ? ' bad' : '');
      d.textContent = msg;
      if (row && row.parentNode) row.parentNode.insertBefore(d, row.nextSibling);
    }

    fetch('/api/checkout', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        domain: DID,
        rung: btn.getAttribute('data-rung'),
        utm: (typeof ATTRIB !== 'undefined' && ATTRIB) ? ATTRIB : null,
        referrer: document.referrer || null
      })
    })
      .then(function (r) { return r.json().then(function (j) { return { status: r.status, j: j }; }); })
      .then(function (res) {
        if (res.j && res.j.ok && res.j.url) { window.location.href = res.j.url; return; }
        say((res.j && res.j.error) || 'Could not start checkout. Try again in a moment.', true);
      })
      .catch(function () { say('Could not reach the payment service. Try again in a moment.', true); });
  });
}

function renderPhaseLadder() {
  var host = EL('phaseLadder'); if (!host) return;
  // Per-domain offers override the generic rungs for P1-P3, the three that actually convert.
  // Each is built from a tool already live on this page, and carries the fastest cadence its
  // SOURCE can truthfully support. Quarterly bank filings cannot promise a daily alert, so
  // Finance does not claim one. Domains without an override fall back to the generic ladder.
  var off = (window.LIMEN_DOMAIN_OFFERS && window.LIMEN_DOMAIN_OFFERS.get(DID)) || null;
  var rows = PHASE_LADDER.map(function (x) {
    if (!off) return x;
    var k = x.p.toLowerCase();
    var o = off[k];
    if (!o) return x;
    return { p: x.p, phase: x.phase, name: o.name, line: o.line, price: o.price, cadence: o.cadence, free: x.free, buy: o.enquire ? null : k, enquire: !!o.enquire };
  });
  host.innerHTML = rows.map(function (x) {
    return '<div class="prow' + (x.free ? ' free' : '') + '"><div class="pnum">' + x.p + '</div>' +
      '<div class="pmid"><span class="pt">' + esc(x.name) + '</span><span class="pph">' + esc(x.phase) + '</span><div class="pl">' + esc(x.line) + '</div>' +
      (x.cadence ? '<div class="pcad">updates ' + esc(x.cadence) + '</div>' : '') + '</div>' +
      '<div class="pprice">' + esc(x.price) +
        (x.buy ? '<button type="button" class="pbuy" data-rung="' + x.buy + '">Subscribe</button>'
               : (x.free ? '' : '<button type="button" class="pbuy" data-enquire="1">Enquire</button>')) +
      '</div></div>';
  }).join('');
  wireBuyButtons(host);
  // Say who this ladder is for, so the reader can self-select instead of guessing.
  if (off && off.who) {
    var sub = host.parentNode && host.parentNode.querySelector('.sub');
    if (sub) sub.innerHTML = 'The live read is free. Everything past it is built for <b>' + esc(off.who) +
      '</b>, and every paid tier is a tool on this page watching your own situation instead of you checking it. ' +
      'Each states the fastest its source can actually move.';
  }
}
renderPhaseLadder();
// ── ATTRIBUTION ────────────────────────────────────────────────────────────
// Where a visitor came from is only in the URL on the FIRST page they land on. Capture it
// once and keep it for the session, or every lead from a social post attributes to nothing
// the moment they click a second link.
var ATTRIB = (function () {
  var KEY = 'limen_attrib';
  var saved = null;
  try { saved = JSON.parse(sessionStorage.getItem(KEY) || 'null'); } catch (e) { saved = null; }
  var q = new URLSearchParams(location.search);
  var fresh = {
    source: q.get('utm_source') || null,
    medium: q.get('utm_medium') || null,
    campaign: q.get('utm_campaign') || null,
    content: q.get('utm_content') || null,
    referrer: (document.referrer || '').slice(0, 300) || null,
    landedOn: '/' + DID
  };
  // A new campaign click overwrites; otherwise keep the original touch.
  if (fresh.source || fresh.campaign || !saved) {
    try { sessionStorage.setItem(KEY, JSON.stringify(fresh)); } catch (e) {}
    return fresh;
  }
  return saved;
})();

/**
 * ONE path for every lead on this page. Previously two of the three capture forms omitted
 * `consent`, which /api/lead REQUIRES, so production answered 400 and the lead was thrown
 * away. Both forms then showed "you're on the list" regardless, because neither checked the
 * response. That is silent data loss behind a false confirmation, so success is now claimed
 * ONLY when the server confirms the write.
 */
function submitLead(payload, els, successText) {
  var btn = els.btn ? EL(els.btn) : null, note = els.note ? EL(els.note) : null;
  var original = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Adding…'; }
  if (note) { note.textContent = ''; note.style.color = ''; }

  var body = {
    email: payload.email,
    consent: true,                      // the form's own copy is the consent notice
    interest: payload.interest,
    message: payload.message || '',
    sourcePage: '/' + DID,
    domain: DID,
    tier: payload.tier || null,
    utm: ATTRIB,
    referrer: ATTRIB.referrer
  };

  function fail(msg) {
    if (btn) { btn.disabled = false; btn.textContent = original; }
    if (note) { note.textContent = msg; note.style.color = 'var(--amber)'; }
  }

  return fetch('/api/lead', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
    .then(function (r) { return r.json().catch(function () { return {}; }).then(function (j) { return { httpOk: r.ok, j: j }; }); })
    .then(function (res) {
      if (!res.httpOk || !res.j || res.j.ok !== true) {
        fail((res.j && res.j.error) ? res.j.error : 'That did not save. Try again in a moment.');
        return false;
      }
      if (els.form) EL(els.form).style.display = 'none';
      if (note) { note.textContent = successText; note.style.color = 'var(--green)'; }
      return true;
    })
    .catch(function () { fail('Network problem. Try again in a moment.'); return false; });
}

function earlyAccess(e) {
  e.preventDefault();
  var email = EL('eaEmail').value.trim(); if (!email) return false;
  submitLead(
    { email: email, interest: C.name + ' add-ons (early access)', tier: 'early-access' },
    { btn: 'eaBtn', note: 'eaNote', form: 'eaForm' },
    '✓ You’re on the early-access list. We’ll reach out as these open up.'
  );
  return false;
}

// ── email capture → /api/lead ──
function subscribe(e) {
  e.preventDefault();
  var email = EL('capEmail').value.trim();
  if (!email) return false;
  submitLead(
    { email: email, interest: C.name, tier: 'watchlist' },
    { btn: 'capBtn', note: 'capNote', form: 'capForm' },
    '✓ You’re on the ' + C.name + ' watchlist.'
  );
  return false;
}